__NUXT_JSONP__("/it/school-calendar", {data:[{details:{slug:"it",pageTitle:"Calendario scolastico | Mentor Language Institute",pageDescription:"La data di inizio del programma varia in base agli studenti di F1 o non F1.",title:"Calendario scolastico",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EGiallo\u003C\u002Ffont\u003E: Data di inizio programma (modulo)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EVerde\u003C\u002Ffont\u003E： no scuola (festivo)"],schoolCalendar:{title:"Calendario scolastico (date di inizio del programma)",description:["\u003Cspan class=\"ymarker\"\u003ELa data di inizio del programma varia in base agli studenti di F1 o non F1.\u003C\u002Fspan\u003E"],lists:[{key:"Studenti non F1 che non ottengono un visto per studenti.",value:["Possono iniziare il loro programma ogni lunedì. \u003Cbr\u003ESe il lunedì è un giorno festivo, la data di inizio del programma sarà martedì per quella settimana."]},{key:"Studenti F1 che ottengono un visto per studenti.",value:["Puoi iniziare in specifici lunedi' (evidenziato in giallo sul calendario).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Domande frequenti sulle date di arrivo negli Stati Uniti",lists:[{key:"\u003Cb\u003ED: Quanti giorni prima della data di inizio del programma uno studente può entrare negli Stati Uniti? \u003C\u002Fb\u003E",value:["A: MLI non richiede ai nostri studenti di entare negli Stati Uniti con un determinato numero di giorni di anticipo. Tuttavia, i nostri studenti di solito entrano negli Stati Uniti 1 o 2 giorni prima della data di inizio del programma."],note:"Nota: gli studenti internazionali possono entrare negli Stati Uniti 30 giorni prima delle date di inizio del programma."},{key:"\u003Cb\u003ED: È possibile spostarsi nella struttura prima delle date di inizio del programma? \u003C\u002Fb\u003E",value:["A: Sì. Siamo in grado di organizzare la tua data di trasloco per qualsiasi altra data\u003Cbr \u002F\u003ESe ci sono altre domande, non esitare a consultarci."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:30.877Z",updatedAt:"2026-04-24T11:47:24.300Z"}}],fetch:{},mutations:void 0});